#!/usr/bin/env python3
"""Standalone pure-Python body calculator and guest-token restore client."""

from __future__ import annotations

import argparse
import base64
import json
import lzma
import pickle
from urllib.parse import unquote, urlsplit


MASK = 0xFFFFFFFF
ARM_CC_AL = 15
BASE = 0x12000000
CORE_INPUT_ADDR = 0x12252000
CORE_KEY_ADDR = 0x122580C0
CORE_R2_ADDR = 0xE4FFF5D4
CORE_R3_ADDR = 0xE4FFF5CC
CORE_STACK_ADDR = 0xE4FFFC00
CORE_STOP = 0x30000000
CORE_KEY_MATERIAL = bytes.fromhex(
    "6240c82db65f24eb0dc47456617ee2ea"
    "4d025a16387b92ffb85b6c93be85ca7d"
    "4132ec165eb453eb78679d98acd2a182"
    "d4ce2beab506f282c975947dccb27e98"
    "5194e6d3f91572fa7aba73d97781f6d3"
    "df536b4d06669ec49f1712f75f4d95c5"
    "c31c978735e648ef459ce971a1c36a27"
    "fab2f2f6d433771c3ae8f8f9d91c38af"
    "a383e147ab402ad08ac061be09edeb34"
    "c298c32442398da1ad0e767b498089d2"
    "f17fe9c49ace20ddd114e1161e225eba"
)
CORE_R2_TEMPLATE = bytes.fromhex(
    "c0802512b000000000000000800000000100000000000000000000006020241201000000000000000100000000000000c08e1812c08e1812635c070f68010000"
)
CORE_R3_TEMPLATE = bytes.fromhex(
    "0000000016000000c0802512b000000000000000800000000100000000000000000000006020241201000000000000000100000000000000c08e1812c08e1812"
)


# Compressed trace program and sparse white-box data are inserted below.
PROGRAM_B64 = """

"""
MODULE_B64 = """

"""
PROGRAM = pickle.loads(lzma.decompress(base64.b64decode(PROGRAM_B64)))
_module_encoded = bytearray(lzma.decompress(base64.b64decode(MODULE_B64)))
for _offset in range(4, len(_module_encoded), 4):
    _previous = int.from_bytes(_module_encoded[_offset - 4 : _offset], "little")
    _current = int.from_bytes(_module_encoded[_offset : _offset + 4], "little") ^ _previous
    _module_encoded[_offset : _offset + 4] = _current.to_bytes(4, "little")
MODULE = bytes(_module_encoded)


class Memory:
    def __init__(self) -> None:
        self.module = bytearray(MODULE)
        self.regions = {
            0x12250000: bytearray(0x20000),
            0xE4FF0000: bytearray(0x20000),
            0x12188000: bytearray(0x20000),
        }

    def _locate(self, address: int, size: int):
        if BASE <= address and address + size <= BASE + len(self.module):
            return self.module, address - BASE
        for start, region in self.regions.items():
            if start <= address and address + size <= start + len(region):
                return region, address - start
        raise RuntimeError(f"unmapped memory: {address:#x} size={size}")

    def read(self, address: int, size: int) -> int:
        region, offset = self._locate(address, size)
        return int.from_bytes(region[offset : offset + size], "little")

    def write(self, address: int, size: int, value: int) -> None:
        region, offset = self._locate(address, size)
        region[offset : offset + size] = int(value & ((1 << (size * 8)) - 1)).to_bytes(size, "little")


def condition_holds(cc: int, flags: dict[str, int]) -> bool:
    if cc == ARM_CC_AL:
        return True
    zf, nf, cf, vf = flags["z"], flags["n"], flags["c"], flags["v"]
    return {
        0: zf == 1,
        1: zf == 0,
        2: cf == 1,
        3: cf == 0,
        4: nf == vf,
        5: nf != vf,
        6: zf == 0 and nf == vf,
        7: zf == 1 or nf != vf,
        8: cf == 1 and zf == 0,
        9: cf == 0 or zf == 1,
        10: nf == 0,
        11: nf == 1,
        12: vf == 0,
        13: vf == 1,
        14: True,
    }.get(cc, True)


def set_sub_flags(flags: dict[str, int], left: int, right: int, result: int) -> None:
    left &= MASK
    right &= MASK
    result &= MASK
    flags["z"] = int(result == 0)
    flags["n"] = (result >> 31) & 1
    flags["c"] = int(left >= right)
    flags["v"] = int(((left ^ right) & (left ^ result) & 0x80000000) != 0)


def shift(value: int, amount: int, kind: str) -> int:
    value &= MASK
    if not amount:
        return value
    if kind == "lsl":
        return (value << amount) & MASK
    if kind == "lsr":
        return value >> amount
    if kind == "asr":
        signed = value if value < 0x80000000 else value - (1 << 32)
        return (signed >> amount) & MASK
    raise RuntimeError(kind)


def _operand_value(regs: list[int], operand) -> int:
    return regs[operand[1]] if operand[0] == "r" else operand[1]


def _address(regs: list[int], memop) -> int:
    base_reg, index_reg, disp, shift_type, shift_value = memop[1:]
    address = (regs[15] & ~3) if base_reg == 15 else (regs[base_reg] if base_reg >= 0 else regs[15])
    if index_reg >= 0:
        index = regs[index_reg]
        if shift_type == 3:
            index >>= shift_value
        elif shift_type == 1:
            signed = index if index < 0x80000000 else index - (1 << 32)
            index = (signed >> shift_value) & MASK
        elif shift_type == 2:
            index = (index << shift_value) & MASK
        address += index
    return (address + disp) & MASK


def execute(program, input_block: bytes, iv: bytes) -> bytes:
    if len(input_block) != 16 or len(iv) != 16:
        raise ValueError("white-box blocks must be exactly 16 bytes")
    regs = [0] * 16
    flags = {"n": 0, "z": 0, "c": 0, "v": 0}
    memory = Memory()
    memory.write(CORE_KEY_ADDR, len(CORE_KEY_MATERIAL), int.from_bytes(CORE_KEY_MATERIAL, "little"))
    input_region = memory.regions[0x12250000]
    input_offset = CORE_INPUT_ADDR - 0x12250000
    input_region[input_offset : input_offset + 64] = bytes(a ^ b for a, b in zip(input_block, iv)) + b"\0" * 48
    memory.regions[0xE4FF0000][CORE_R2_ADDR - 0xE4FF0000 : CORE_R2_ADDR - 0xE4FF0000 + len(CORE_R2_TEMPLATE)] = CORE_R2_TEMPLATE
    memory.regions[0xE4FF0000][CORE_R3_ADDR - 0xE4FF0000 : CORE_R3_ADDR - 0xE4FF0000 + len(CORE_R3_TEMPLATE)] = CORE_R3_TEMPLATE
    regs[0], regs[1], regs[2], regs[3], regs[13], regs[14] = (
        CORE_INPUT_ADDR,
        CORE_INPUT_ADDR,
        CORE_R2_ADDR,
        CORE_R3_ADDR,
        CORE_STACK_ADDR,
        CORE_STOP,
    )

    for pc, mnemonic, cc, operands in program:
        regs[15] = BASE + pc
        if not condition_holds(cc, flags):
            continue
        regs[15] = BASE + pc + 4
        name = mnemonic.removesuffix(".w")
        if name in {"b", "bx", "bl", "blx", "it", "ite", "itt", "ittt", "beq", "bhi"}:
            continue
        if name == "push":
            regs[13] = (regs[13] - 4 * len(operands)) & MASK
            for index, operand in enumerate(operands):
                memory.write(regs[13] + index * 4, 4, regs[operand[1]])
            continue
        if name == "pop":
            for index, operand in enumerate(operands):
                value = memory.read(regs[13] + index * 4, 4)
                if operand[1] != 15:
                    regs[operand[1]] = value
            regs[13] = (regs[13] + 4 * len(operands)) & MASK
            continue
        if name in {"mov", "movs", "movw"}:
            regs[operands[0][1]] = _operand_value(regs, operands[1]) & MASK
            continue
        if name == "adr":
            regs[operands[0][1]] = (regs[15] & ~3) + operands[1][1]
            continue
        if name in {"ldr", "ldrb"}:
            regs[operands[0][1]] = memory.read(_address(regs, operands[1]), 1 if name == "ldrb" else 4)
            continue
        if name in {"str", "strb"}:
            memory.write(_address(regs, operands[1]), 1 if name == "strb" else 4, regs[operands[0][1]])
            continue
        if name in {"add", "adds", "sub", "subs", "rsb", "mul", "mls", "bics"}:
            dst = operands[0][1]
            if len(operands) == 2:
                left, right = regs[dst], _operand_value(regs, operands[1])
            else:
                left = regs[operands[1][1]]
                right = _operand_value(regs, operands[2])
                if operands[2][0] == "r" and operands[2][3]:
                    shift_kind = {1: "asr", 2: "lsl", 3: "lsr", 4: "ror"}.get(operands[2][2], "lsl")
                    if shift_kind == "ror":
                        amount = operands[2][3] & 31
                        right = ((right >> amount) | (right << (32 - amount))) & MASK if amount else right
                    else:
                        right = shift(right, operands[2][3], shift_kind)
            if name.startswith("add"):
                value = left + right
            elif name.startswith("sub"):
                value = left - right
            elif name == "rsb":
                value = right - left
            elif name == "mul":
                value = left * right
            elif name == "mls":
                value = regs[operands[3][1]] - regs[operands[1][1]] * regs[operands[2][1]]
            else:
                value = left & ~right
            regs[dst] = value & MASK
            if name in {"adds", "subs", "bics"}:
                if name == "subs":
                    set_sub_flags(flags, left, right, value)
                else:
                    flags["z"] = int((value & MASK) == 0)
                    flags["n"] = (value >> 31) & 1
            continue
        if name in {"lsls", "lsrs", "asrs", "lsr"}:
            dst, src = operands[0][1], operands[1][1]
            amount = _operand_value(regs, operands[2])
            kind = {"lsls": "lsl", "lsrs": "lsr", "asrs": "asr", "lsr": "lsr"}[name]
            regs[dst] = shift(regs[src], amount, kind)
            flags["z"] = int(regs[dst] == 0)
            flags["n"] = (regs[dst] >> 31) & 1
            continue
        if name == "uxtb":
            regs[operands[0][1]] = regs[operands[1][1]] & 0xFF
            continue
        if name == "ubfx":
            lsb, width = operands[2][1], operands[3][1]
            regs[operands[0][1]] = (regs[operands[1][1]] >> lsb) & ((1 << width) - 1)
            continue
        if name == "cmp":
            left = regs[operands[0][1]]
            right = _operand_value(regs, operands[1])
            set_sub_flags(flags, left, right, left - right)
            continue
        raise RuntimeError(f"unsupported instruction {mnemonic} {operands}")
    return bytes(input_region[input_offset : input_offset + 16])


def _permute_byte(value: int, mapping: tuple[int, ...]) -> int:
    return sum(((value >> src) & 1) << dst for src, dst in enumerate(mapping))


def table_e(value: int) -> int:
    return _permute_byte(value, (3, 5, 0, 6, 2, 7, 4, 1))


def table_a(value: int) -> int:
    return table_e(value) ^ 0xA4


def table_c(value: int) -> int:
    return _permute_byte(value, (2, 7, 4, 0, 6, 1, 3, 5))


IV_ASCII = b"d58b45f9acc1a1f6"
KNOWN_URL = (
    "https://soia.zhihu.com/km_paid_content/share?"
    "is_delivery=true&source=e9f03bea58b4524092f6cb42207b6a5f&"
    "package=zhihushare0812&channel_id=67154024128158&appkey=2400&"
    "ustkn=1&is_share_data=true&fallback_url=zhvip%3A%2F%2Ftab%2Fhome&"
    "mst=lrNQ89GWjLoJBcqLdkWA0wyJKmua0p4Nl"
)
KNOWN_BODY = (
    "vS7z8K4mA7mcss2fo0u2IFO2XXNOnt4zKobKMq6Ndgj8s1381eln06+Tt/8ORMHI"
    "hCAtMt+CopxswOfzFkee+P0QZlUPpuZawwIRCKITftA7u6QJsxcvnSzgYz5jtThqK"
    "Lm6LAxnGZzpIkjH+DB/y6Rb8iSCkq1Del6sFcXXhUIMCO3Aa4DFkA/o4kxQkFEp0"
    "gTuxMoKEcKbiC8CtcmLVJ29eEVHawcWzGy8a7sF5NfSpooIfW7rah1OVy11CRpFS"
    "XX4vgLSqz5Eu3etVtI7pUcmUc9iDAGFte4P4kbhuzsBeaqTXzeCTXjz4haombXMA"
    "XdwU89oWzwRqa6uUcRPyQ=="
)


def build_plaintext(share_url: str) -> bytes:
    query_info = unquote(urlsplit(share_url).query)
    return json.dumps(
        {"query_info": query_info, "scene": "soia"},
        separators=(",", ":"),
        ensure_ascii=False,
    ).encode("utf-8")


def calculate_body(share_url: str) -> tuple[bytes, str]:
    plaintext = build_plaintext(share_url)
    native_input = bytes(table_a(value) for value in plaintext)
    native_iv = bytes(table_e(value) for value in IV_ASCII)
    pad = 16 - (len(native_input) % 16)
    padded = native_input + bytes([table_a(pad)]) * pad
    output = bytearray()
    previous = native_iv
    for offset in range(0, len(padded), 16):
        block = padded[offset : offset + 16]
        output.extend(execute(PROGRAM, block, previous))
        previous = bytes(output[-16:])
    final_bytes = bytes(table_c(value) for value in output)
    return plaintext, base64.b64encode(final_bytes).decode("ascii")


import datetime as dt
import os
import random
import urllib.error
import urllib.request
import uuid
from pathlib import Path



ROOT = Path(__file__).resolve().parent
GUEST_TOKEN_URL = "https://api.zhihu.com/api/account/prod/guests/token"
RESTORE_URL = "https://api.zhihu.com/kmap/share_restore"
CACHE_PATH = ROOT / "zhihu_guest_tokens.json"

# Previously captured device identifiers. Pass --udid to replace this pool.
DEFAULT_UDIDS = (
    "Z6dZxlqytRxgCcBiUhdxcVBqD3jJMhmBDos=",
    "X5AZXRZUsBxgCQTsr9GXPrFpkrHK-pxngXU=",
    "a9f8c47de11b4f09a5db7a396e40b613",
)

GUEST_USER_AGENT = (
    "com.zhihu.android/Futureve/8.47.0 com.zhihu.vip.android/zhvip/1.45.0 "
    "Mozilla/5.0 (Linux; Android 12; SM-G9900 Build/V417IR; wv) "
    "AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 "
    "Chrome/57.0.1000.10 Mobile Safari/537.36"
)
RESTORE_USER_AGENT = (
    "com.zhihu.android/Futureve/8.47.0 com.zhihu.vip.android/zhvip/1.45.0 "
    "Mozilla/5.0 (Linux; Android 12; SM-G9900 Build/V417IR; wv) "
    "AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 "
    "Chrome/110.0.5481.154 Safari/537.36"
)


def today() -> str:
    return dt.date.today().isoformat()


def load_state(path: Path) -> dict:
    if not path.exists():
        return {"next_index": 0, "tokens": {}}
    try:
        state = json.loads(path.read_text("utf-8"))
    except (OSError, ValueError):
        return {"next_index": 0, "tokens": {}}
    if not isinstance(state, dict):
        return {"next_index": 0, "tokens": {}}
    state.setdefault("next_index", 0)
    state.setdefault("tokens", {})
    return state


def save_state(path: Path, state: dict) -> None:
    path.write_text(json.dumps(state, ensure_ascii=False, indent=2) + "\n", "utf-8")


def token_from_json(value) -> str:
    """Find a token across the response shapes used by guest-token builds."""
    if isinstance(value, dict):
        for key in ("token", "access_token", "guest_token", "authorization"):
            candidate = value.get(key)
            if isinstance(candidate, str) and candidate.strip():
                return candidate.strip()
        for child in value.values():
            found = token_from_json(child)
            if found:
                return found
    elif isinstance(value, list):
        for child in value:
            found = token_from_json(child)
            if found:
                return found
    return ""


def post(url: str, headers: dict[str, str], body: bytes = b"") -> tuple[int, bytes]:
    request = urllib.request.Request(url, data=body, headers=headers, method="POST")
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            return response.status, response.read()
    except urllib.error.HTTPError as exc:
        return exc.code, exc.read()


def fetch_guest_token(udid: str) -> str:
    status, raw = post(
        GUEST_TOKEN_URL,
        {
            "User-Agent": GUEST_USER_AGENT,
            "Content-Type": "application/x-www-form-urlencoded",
            "X-Zse-93": "none",
            "x-udid": udid,
            "Content-Length": "0",
        },
    )
    try:
        payload = json.loads(raw.decode("utf-8", "replace"))
    except ValueError:
        payload = {"raw": raw.decode("utf-8", "replace")}
    token = token_from_json(payload)
    if status < 200 or status >= 300 or not token:
        raise RuntimeError(f"guest token failed for {udid}: HTTP {status} {payload}")
    return token.removeprefix("Bearer ").strip()


def get_token(udid: str, state: dict, force: bool = False) -> str:
    record = state["tokens"].get(udid, {})
    if not force and record.get("date") == today() and record.get("token"):
        return str(record["token"])
    token = fetch_guest_token(udid)
    state["tokens"][udid] = {"date": today(), "token": token}
    return token


def choose_udid(udids: list[str], state: dict, randomize: bool) -> str:
    if randomize:
        return random.choice(udids)
    index = int(state.get("next_index", 0)) % len(udids)
    state["next_index"] = (index + 1) % len(udids)
    return udids[index]


def restore(share_url: str, udid: str, token: str, request_body: str | None = None) -> tuple[int, bytes]:
    body = request_body if request_body is not None else calculate_body(share_url)[1]
    return post(
        RESTORE_URL,
        {
            "User-Agent": RESTORE_USER_AGENT,
            "Connection": "Keep-Alive",
            "Accept-Encoding": "br,gzip",
            "X-B3-Traceid": uuid.uuid4().hex,
            "X-Zse-93": "204_1_3.0",
            "x-app-version": "1.45.0",
            "x-app-za": "1",
            "x-udid": udid,
            "Authorization": "Bearer " + token,
            "Content-Type": "application/json; charset=UTF-8",
        },
        body.encode("ascii"),
    )


def parse_udids(args: argparse.Namespace) -> list[str]:
    values = list(args.udid or [])
    if args.udids_file:
        values.extend(
            line.strip()
            for line in Path(args.udids_file).read_text("utf-8").splitlines()
            if line.strip() and not line.lstrip().startswith("#")
        )
    values.extend(x.strip() for x in os.environ.get("ZHIHU_UDIDS", "").split(",") if x.strip())
    result = list(dict.fromkeys(values))
    return result or list(DEFAULT_UDIDS)


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("share_url", nargs="?", help="share URL; omit to enter it")
    parser.add_argument("--udid", action="append", help="UDID; repeat for a pool")
    parser.add_argument("--udids-file", type=Path)
    parser.add_argument("--cache", type=Path, default=CACHE_PATH)
    parser.add_argument("--random", action="store_true", help="random selection instead of round-robin")
    parser.add_argument("--refresh", action="store_true", help="refresh the selected UDID token now")
    args = parser.parse_args()

    share_url = args.share_url or input("share_url> ").strip()
    if not share_url:
        parser.error("a share URL is required")
    udids = parse_udids(args)
    state = load_state(args.cache)
    request_body = calculate_body(share_url)[1]
    errors: list[str] = []
    status = 0
    raw = b""

    try:
        for _ in range(len(udids)):
            udid = choose_udid(udids, state, args.random)
            try:
                token = get_token(udid, state, force=args.refresh)
                status, raw = restore(share_url, udid, token, request_body)
                if status in (401, 403):
                    state["tokens"].pop(udid, None)
                    token = get_token(udid, state, force=True)
                    status, raw = restore(share_url, udid, token, request_body)
                break
            except Exception as exc:
                errors.append(f"{udid}: {exc}")
        else:
            raise RuntimeError("all UDIDs failed: " + " | ".join(errors))
    finally:
        save_state(args.cache, state)

    print("udid=" + udid)
    print("request_body=" + request_body)
    print("HTTP " + str(status))
    print(raw.decode("utf-8", "replace"))


if __name__ == "__main__":
    main()
